where code = 'ORMOC-SOGOD';

insert into public.stops (id, name, location) values
  ('31000000-0000-4000-8000-000000000001', 'Ormoc City South Terminal', ST_GeogFromText('POINT(124.609389 11.009037)')),
  ('31000000-0000-4000-8000-000000000002', 'Albuera Poblacion', ST_GeogFromText('POINT(124.694366 10.916655)')),
  ('31000000-0000-4000-8000-000000000003', 'Baybay Public Terminal', ST_GeogFromText('POINT(124.798280 10.675341)')),
  ('31000000-0000-4000-8000-000000000006', 'Hilongos Poblacion', ST_GeogFromText('POINT(124.748817 10.373300)')),
  ('31000000-0000-4000-8000-000000000007', 'Bato Poblacion', ST_GeogFromText('POINT(124.789324 10.327930)')),
  ('31000000-0000-4000-8000-000000000005', 'Sogod Bus Terminal', ST_GeogFromText('POINT(124.983005 10.383990)'))
on conflict (id) do update
set name = excluded.name,
    location = excluded.location;

delete from public.route_stops
where route_id = (select id from public.routes where code = 'ORMOC-SOGOD');

insert into public.route_stops (route_id, stop_id, sequence)
select route.id, stop.stop_id, stop.sequence
from (select id from public.routes where code = 'ORMOC-SOGOD') route
cross join (values
  ('31000000-0000-4000-8000-000000000001'::uuid, 1),
  ('31000000-0000-4000-8000-000000000002'::uuid, 2),
  ('31000000-0000-4000-8000-000000000003'::uuid, 3),
  ('31000000-0000-4000-8000-000000000006'::uuid, 4),
  ('31000000-0000-4000-8000-000000000007'::uuid, 5),
  ('31000000-0000-4000-8000-000000000005'::uuid, 6)
) as stop(stop_id, sequence);
